import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
const load = path => import(pathToFileURL(resolve(path)).href);
const { validateArtifactRef, validateProfile, validateManifest, CONTRACTS } = await load('packages/kernel/src/contracts/index.ts');
const { resolveDeviceProfile } = await load('packages/source/src/clockwork/control-contracts.ts');
const { parseRegionRead, REGION_LIMITS } = await load('packages/play/src/venues/phone/companion.ts');
const rows = [];
function attempt(id, input, fn, expectedConstraint) {
  try { const result = fn(input); rows.push({ id, input, expectedConstraint, accepted: true,
    summary: id.startsWith('region') ? { seq: String(result.seq), regions: Object.keys(result.regions).length,
      samples: Object.values(result.regions).reduce((sum, value) => sum + value.pixels.length, 0),
      geometry: Object.values(result.regions).map(({width,height,step}) => ({width,height,step})) } : result }); }
  catch (error) { rows.push({ id, input, expectedConstraint, accepted: false, error: error.message }); }
}
const profile = { schema: 'device-profile-v1', id: 'probe', targetBuild: 'com.scottgames.fnaf2:2.0.7+26',
  actuator: 'probe', visualSensor: 'probe', visualDetector: 'probe', clock: 'device-monotonic-ms',
  calibrations: { bad: 123 }, controlMap: { mask: { x: 'bad', y: null } } };
attempt('profile-nested-type-mismatch', profile, validateProfile, 'calibrations values are strings, controlMap points have numeric x/y');
attempt('resolved-profile-nested-type-mismatch', profile, resolveDeviceProfile, 'same nested types after resolution');
attempt('artifact-size-nan', {schema:'artifact-ref-v1',hash:'h',mediaType:'x',producer:'p',size:NaN}, validateArtifactRef, 'resource sizes must be finite');
attempt('manifest-artifacts-array', {schema:'session-manifest-v1',id:'probe',profileHash:'h',targetBuild:'b',events:[],artifacts:[]}, validateManifest, 'artifacts is a Record<string,unknown>');
attempt('region-seq-non-finite', 'OK seq=' + '9'.repeat(400), parseRegionRead, 'seq is a finite safe integer');
attempt('region-duplicate-seq', 'OK seq=1 seq=2', parseRegionRead, 'duplicate measurement key is ambiguous');
attempt('region-over-step-limit', 'OK seq=1 r=0,0,1,1,65:000000', parseRegionRead, 'step <= ' + REGION_LIMITS.step);
attempt('region-over-sample-limit', 'OK seq=1 r=0,0,8193,1,1:' + '000000'.repeat(8193), parseRegionRead, 'samples <= ' + REGION_LIMITS.samples);
attempt('region-over-count-limit', 'OK seq=1 ' + Array.from({length:17},(_,i) => 'r'+i+'=0,0,1,1,1:000000').join(' '), parseRegionRead, 'regions <= ' + REGION_LIMITS.regions);
const output = { label:'FIXTURE', limits:REGION_LIMITS, contractIdArrayIncludesClaimEnvelope:CONTRACTS.includes('claim-envelope-v1'), probes:rows };
writeFileSync('artifacts/types-contracts-health-20261005/probes.json', JSON.stringify(output, (_, value) =>
  typeof value === 'number' && !Number.isFinite(value) ? String(value) : value, 2) + '\n');
for (const row of rows) console.log(JSON.stringify({id:row.id,accepted:row.accepted,expectedConstraint:row.expectedConstraint}));
